-        return view[index];
+    explicit QueueRefs(const std::vector<Pointer>& resources) : borrowed(resources) {}
+    QueueRefs(std::initializer_list<Pointer> resources) : count(resources.size()), owns(true) {
+        if (count > local.size()) throw std::out_of_range("diagnostic QueueRefs capacity");
+        std::copy(resources.begin(), resources.end(), local.begin());
     }
+    std::size_t size() const { return owns ? count : borrowed.size(); }
