+        for (std::size_t i=0;i<count;++i) if(queues[i]==queue) return;
+        if(count==queues.size()) throw std::out_of_range("diagnostic Pops capacity");
+        queues[count++]=queue;
         queue->proposePop(rule);
     }
 };
