    start = Clock::now();
    if (fixed) {
      for (std::uint64_t i = 0; i < fixed; ++i)
        cpu.sim.step();
    } else {
      while (cpu.sim.tick() < limit && !cpu.control.peek().stopped) {
        cpu.sim.step();
        if (!benchmark)
          snapshot();
      }
    }
    auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
                       Clock::now() - start)
                       .count();
    profile_control("disable\n");
    if (!fixed && !cpu.control.peek().stopped)
      throw std::runtime_error("cycle bound exceeded");
    struct rusage usage{};
    getrusage(RUSAGE_SELF, &usage);
    std::cout << "{\"final\":true,\"cycles\":" << cpu.sim.tick()
              << ",\"instructions\":" << cpu.retirement.peek().count
              << ",\"stopped\":" << cpu.control.peek().stopped;
    if (benchmark) {
      std::cout << ",\"measured_cycles\":" << cpu.sim.tick() - warmup
                << ",\"measured_instructions\":"
                << cpu.retirement.peek().count - instructionsBefore
                << ",\"run_ns\":" << elapsed
                << ",\"construct_ns\":" << construct
                << ",\"max_rss_kib\":" << usage.ru_maxrss;
      const auto &stats = cpu.sim.stats();
      std::cout << ",\"module_work\":" << stats.moduleWork
                << ",\"rule_work\":" << stats.ruleWork
                << ",\"arbitration_attempts\":" << stats.arbitrationAttempts
                << ",\"delta_rounds\":" << stats.deltaRounds
                << ",\"queue_checks\":" << stats.queueChecks
                << ",\"accepted\":" << stats.accepted
                << ",\"events\":" << stats.events
                << ",\"due_events\":" << stats.dueEvents;
    }
    {
      std::cout << ",\"registers\":[";
      for (unsigned i = 0; i < 32; ++i) {
        if (i)
          std::cout << ',';
        std::cout << cpu.registers.refs[i]->peek();
      }
      std::cout << "],\"memory_changes\":[";
      bool comma = false;
      for (std::size_t i = 0; i < data.size(); ++i) {
        auto now = cpu.data.refs[i]->peek();
        for (unsigned j = 0; j < 4; ++j) {
          auto a = (data[i] >> (8 * j)) & 255, b = (now >> (8 * j)) & 255;
          if (a != b) {
            if (comma)
              std::cout << ',';
            comma = true;
            std::cout << '[' << i * 4 + j << ',' << b << ']';
          }
        }
      }
      std::cout << ']';
    }
    std::cout << "}\n";
  } catch (const std::exception &e) {
    std::cerr << e.what() << '\n';
    return 1;
  }
}

