from pathlib import Path
out=Path('/tmp/gfsim-slots-analysis');runner=(out/'runner.cpp').read_text()
code=r'''
#include <new>
struct AllocationStats {
    std::uint64_t calls{}, bytes{}, frees{};
    std::array<std::uint64_t,257> sizes{};
};
static bool countAllocations{};
static AllocationStats allocations;
void* operator new(std::size_t n) {
    if (countAllocations) {
        ++allocations.calls; allocations.bytes += n;
        ++allocations.sizes[std::min(n, std::size_t{256})];
    }
    if (void* p=std::malloc(n ? n : 1)) return p;
    throw std::bad_alloc();
}
void* operator new[](std::size_t n) { return ::operator new(n); }
void operator delete(void* p) noexcept {
    if (countAllocations && p) ++allocations.frees;
    std::free(p);
}
void operator delete[](void* p) noexcept { ::operator delete(p); }
void operator delete(void* p, std::size_t) noexcept { ::operator delete(p); }
void operator delete[](void* p, std::size_t) noexcept { ::operator delete(p); }
'''
