              << ",\"bytes\":" << measuredAllocations.bytes << ",\"frees\":" << measuredAllocations.frees
              << ",\"sizes\":[";
    for (std::size_t i=0;i<measuredAllocations.sizes.size();++i)
        std::cout << (i ? "," : "") << measuredAllocations.sizes[i];
    std::cout << "]}";
'''
